import React, { useEffect, useRef } from 'react';
import L from 'leaflet';
import '../styles/Map.css';

// Fix for default markers
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

// Generated by generate-thumbnails.js; Drive URLs need auth, so they aren't used here
const thumbUrl = (art) => `${import.meta.env.BASE_URL}thumbs/${art.id}.jpg`;

const escapeHtml = (s = '') =>
  String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

function Map({ cities }) {
  const mapContainer = useRef(null);
  const map = useRef(null);
  const markersRef = useRef([]);

  useEffect(() => {
    if (!mapContainer.current || !cities) return;

    // Initialize map
    if (!map.current) {
      map.current = L.map(mapContainer.current).setView([27.7, 85.3], 4);

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors',
        maxZoom: 19
      }).addTo(map.current);
    }

    // Clear existing markers
    markersRef.current.forEach(marker => marker.remove());
    markersRef.current = [];

    // Add markers for cities with artworks
    cities.forEach((city) => {
      if (city.artworks && city.artworks.length > 0) {
        const marker = L.circleMarker([city.lat, city.lng], {
          radius: 15,
          fillColor: '#ff6b6b',
          color: '#fff',
          weight: 3,
          opacity: 1,
          fillOpacity: 0.85
        });

        // Popup HTML is built only when opened; images load lazily as the grid scrolls
        const buildPopup = () => `
          <div class="city-popup">
            <h3>📍 ${escapeHtml(city.city)}</h3>
            <p><strong>${escapeHtml(city.country)}</strong></p>
            <p><strong>${city.artworks.length}</strong> street art photos</p>
            <div class="photo-grid">
              ${city.artworks.map(art => `
                <div class="photo-thumb" title="${escapeHtml(art.fileName)}">
                  <img src="${thumbUrl(art)}" alt="${escapeHtml(art.fileName)}"
                       loading="lazy" decoding="async" width="80" height="80"
                       onerror="this.replaceWith(Object.assign(document.createElement('span'),{textContent:this.alt}))" />
                </div>
              `).join('')}
            </div>
          </div>
        `;

        marker.bindPopup(buildPopup, { maxWidth: 400, minWidth: 300 })
          .addTo(map.current);

        markersRef.current.push(marker);
      }
    });

    // Fit bounds if there are markers
    if (markersRef.current.length > 0) {
      try {
        const group = new L.featureGroup(markersRef.current);
        const bounds = group.getBounds();
        if (bounds.isValid()) {
          map.current.fitBounds(bounds, { padding: [50, 50], maxZoom: 10 });
        }
      } catch (err) {
        console.warn('Error fitting bounds:', err);
      }
    }

  }, [cities]);

  return <div ref={mapContainer} className="map" />;
}

export default Map;
